//! Entire old required-list validation over the real complete registration factory.
#[path="../fixtures/original_policies/required_scope_validation.rs"]mod original;
#[test]fn unique_required_scope_loop_matches_frozen_original_complete_registry_and_actual_scopes(){let registry=crate::run::registry();let loaded=crate::scopes::Scopes::parse(include_str!("../../ci/lint_scopes.toml")).unwrap();for scopes in [&crate::scopes::Scopes::default(),&loaded]{let expected=original::Original{reg:&registry,scopes}.validate_scopes();let actual=crate::required_scope_policy::validate_using(registry.lints.iter().map(|lint|{let meta=lint.meta();crate::required_scope_policy::Requirement{name:meta.name,group:meta.group,lists:meta.lists}}),scopes,&mut crate::key_policy_control::Compatibility).unwrap();assert_eq!(actual,expected,"all registered names, groups, required keys and error order");}let empty=crate::scopes::Scopes::default();let expected=original::Original{reg:&registry,scopes:&empty}.validate_scopes();assert!(!expected.is_empty(),"actual complete factory must exercise required keys");}
